WORD32 ihevcd_ref_list(codec_t *ps_codec, pps_t *ps_pps, sps_t *ps_sps, slice_header_t *ps_slice_hdr)
{
    WORD32 i, j;
    WORD32 st_rps_idx;
    WORD32 num_neg_pics, num_pos_pics;
    WORD8 *pi1_used;
    WORD16 *pi2_delta_poc;
    UWORD32 u4_max_poc_lsb;
    pic_buf_t *ps_pic_buf;
    mv_buf_t *ps_mv_buf;
    UWORD32 r_idx;

    dpb_mgr_t *ps_dpb_mgr = (dpb_mgr_t *)ps_codec->pv_dpb_mgr;
    buf_mgr_t *ps_mv_buf_mgr = (buf_mgr_t *)ps_codec->pv_mv_buf_mgr;

    WORD32 ai4_poc_st_curr_before[MAX_DPB_SIZE], ai4_poc_st_foll[MAX_DPB_SIZE], ai4_poc_st_curr_after[MAX_DPB_SIZE];
    WORD32 ai4_poc_lt_curr[MAX_DPB_SIZE], ai4_poc_lt_foll[MAX_DPB_SIZE];
    UWORD32 u4_num_st_curr_before, u4_num_st_foll, u4_num_st_curr_after, u4_num_lt_curr, u4_num_lt_foll;
    UWORD32 u4_num_total_curr;

    WORD8 ai1_curr_delta_poc_msb_present_flag[MAX_DPB_SIZE], ai1_foll_delta_poc_msb_present_flag[MAX_DPB_SIZE];

    pic_buf_t *as_ref_pic_lt_curr[MAX_DPB_SIZE];
    pic_buf_t *as_ref_pic_lt_foll[MAX_DPB_SIZE];
    pic_buf_t *as_ref_pic_st_curr_after[MAX_DPB_SIZE];
    pic_buf_t *as_ref_pic_st_curr_before[MAX_DPB_SIZE];
    pic_buf_t *as_ref_pic_st_foll[MAX_DPB_SIZE];

    pic_buf_t *as_ref_pic_list_temp0[MAX_DPB_SIZE], *as_ref_pic_list_temp1[MAX_DPB_SIZE];

    UWORD32 u4_num_rps_curr_temp_list0, u4_num_rps_curr_temp_list1;

    WORD32 i4_pic_order_cnt_val;
    WORD32 i4_poc_lt;
    UNUSED(as_ref_pic_lt_foll);
    UNUSED(as_ref_pic_st_foll);
    UNUSED(ps_pps);

    RETURN_IF_NAL_INFO;

    u4_max_poc_lsb = (1 << ps_sps->i1_log2_max_pic_order_cnt_lsb);

    i4_pic_order_cnt_val = ps_slice_hdr->i4_abs_pic_order_cnt;

    if(1 == ps_slice_hdr->i1_short_term_ref_pic_set_sps_flag)
    {
        st_rps_idx = ps_slice_hdr->i1_short_term_ref_pic_set_idx;
        num_neg_pics = ps_sps->as_stref_picset[st_rps_idx].i1_num_neg_pics;
        num_pos_pics = ps_sps->as_stref_picset[st_rps_idx].i1_num_pos_pics;
        pi1_used = ps_sps->as_stref_picset[st_rps_idx].ai1_used;
        pi2_delta_poc = ps_sps->as_stref_picset[st_rps_idx].ai2_delta_poc;
    }
    else
    {
        st_rps_idx = ps_sps->i1_num_short_term_ref_pic_sets;
        num_neg_pics = ps_slice_hdr->s_stref_picset.i1_num_neg_pics;
        num_pos_pics = ps_slice_hdr->s_stref_picset.i1_num_pos_pics;
        pi1_used = ps_slice_hdr->s_stref_picset.ai1_used;
        pi2_delta_poc = ps_slice_hdr->s_stref_picset.ai2_delta_poc;
    }

    u4_num_st_curr_before = 0;
    u4_num_st_foll = 0;
    for(i = 0; i < num_neg_pics; i++)
    {
        if(pi1_used[i])
        {
            ai4_poc_st_curr_before[u4_num_st_curr_before] = i4_pic_order_cnt_val + pi2_delta_poc[i];
            u4_num_st_curr_before++;
        }
        else
        {
            ai4_poc_st_foll[u4_num_st_foll] = i4_pic_order_cnt_val + pi2_delta_poc[i];
            u4_num_st_foll++;
        }
    }
    u4_num_st_curr_after = 0;
    for(i = num_neg_pics; i < num_neg_pics + num_pos_pics; i++)
    {
        if(pi1_used[i])
        {
            ai4_poc_st_curr_after[u4_num_st_curr_after] = i4_pic_order_cnt_val + pi2_delta_poc[i];
            u4_num_st_curr_after++;
        }
        else
        {
            ai4_poc_st_foll[u4_num_st_foll] = i4_pic_order_cnt_val + pi2_delta_poc[i];
            u4_num_st_foll++;
        }
    }

    u4_num_lt_curr = 0;
    u4_num_lt_foll = 0;
    for(i = 0; i < ps_slice_hdr->i1_num_long_term_sps + ps_slice_hdr->i1_num_long_term_pics; i++)
    {
        i4_poc_lt = ps_slice_hdr->ai4_poc_lsb_lt[i];
        if(ps_slice_hdr->ai1_delta_poc_msb_present_flag[i])
        {
            i4_poc_lt += i4_pic_order_cnt_val - ps_slice_hdr->ai1_delta_poc_msb_cycle_lt[i] * (WORD32)u4_max_poc_lsb - ps_slice_hdr->i4_pic_order_cnt_lsb;
        }

        if(ps_slice_hdr->ai1_used_by_curr_pic_lt_flag[i])
        {
            ai4_poc_lt_curr[u4_num_lt_curr] = i4_poc_lt;
            ai1_curr_delta_poc_msb_present_flag[u4_num_lt_curr] = ps_slice_hdr->ai1_delta_poc_msb_present_flag[i];
            u4_num_lt_curr++;
        }
        else
        {
            ai4_poc_lt_foll[u4_num_lt_foll] = i4_poc_lt;
            ai1_foll_delta_poc_msb_present_flag[u4_num_lt_foll] = ps_slice_hdr->ai1_delta_poc_msb_present_flag[i];
            u4_num_lt_foll++;
        }
    }

    u4_num_total_curr = u4_num_lt_curr + u4_num_st_curr_after + u4_num_st_curr_before;

    /* Bit stream conformance tests */
/*
    for(i = 0; i < u4_num_lt_curr; i++)
    {
        int j;
        if(ai1_curr_delta_poc_msb_present_flag[i])
        {
            for(j = 0; j < u4_num_st_curr_before; j++)
            {
                ASSERT(ai4_poc_st_curr_before[j] != ai4_poc_lt_curr[i]);
            }
            for(j = 0; j < u4_num_st_curr_after; j++)
            {
                ASSERT(ai4_poc_st_curr_after[j] != ai4_poc_lt_curr[i]);
            }
            for(j = 0; j < u4_num_st_foll; j++)
            {
                ASSERT(ai4_poc_st_foll[j] != ai4_poc_lt_curr[i]);
            }
            for(j = 0; j < u4_num_lt_curr; j++)
            {
                ASSERT((ai4_poc_lt_curr[j] != ai4_poc_lt_curr[i]) || (j == i));
            }
        }
        else
        {
            for(j = 0; j < u4_num_st_curr_before; j++)
            {
                ASSERT((ai4_poc_st_curr_before[j] & (u4_max_poc_lsb - 1)) != ai4_poc_lt_curr[i]);
            }
            for(j = 0; j < u4_num_st_curr_after; j++)
     1  *  Parse Slice Header
     2  * slice_header_syntax()
     3  *
     4  * @par Description:
     5  *  Parse Slice Header as per  Section: 7.3.8
     6  *
     7  * @param[in] ps_codec
     8  *  Pointer to codec context
     9  *
    10  * @returns  Error code from IHEVCD_ERROR_T
    11  *
    12  * @remarks
    13  *
    14  *
    15  *******************************************************************************
    16  */
    17
    18  IHEVCD_ERROR_T ihevcd_parse_slice_header(codec_t *ps_codec,
    19                                           nal_header_t *ps_nal)
    20  {
    21      IHEVCD_ERROR_T ret = (IHEVCD_ERROR_T)IHEVCD_SUCCESS;
    22      UWORD32 value;
    23      WORD32 i4_value;
    24      WORD32 i, j;
    25      WORD32 sps_id;
    26
    27      pps_t *ps_pps;
    28      sps_t *ps_sps;
    29      slice_header_t *ps_slice_hdr;
    30      WORD32 disable_deblocking_filter_flag;
    31      bitstrm_t *ps_bitstrm = &ps_codec->s_parse.s_bitstrm;
    32      WORD32 idr_pic_flag;
    33      WORD32 pps_id;
    34      WORD32 first_slice_in_pic_flag;
    35      WORD32 no_output_of_prior_pics_flag = 0;
    36      WORD8 i1_nal_unit_type = ps_nal->i1_nal_unit_type;
    37      WORD32 num_poc_total_curr = 0;
    38      UWORD32 slice_address;
    39      WORD32 prev_slice_incomplete_flag = 0;
    40
    41      if(ps_codec->i4_slice_error == 1)
    42          return ret;
    43
    44      idr_pic_flag = (NAL_IDR_W_LP == i1_nal_unit_type) ||
    45                      (NAL_IDR_N_LP == i1_nal_unit_type);
    46
    47
    48      BITS_PARSE("first_slice_in_pic_flag", first_slice_in_pic_flag, ps_bitstrm, 1);
    49      if((NAL_BLA_W_LP <= i1_nal_unit_type) &&
    50         (NAL_RSV_RAP_VCL23          >= i1_nal_unit_type))
    51      {
    52          BITS_PARSE("no_output_of_prior_pics_flag", no_output_of_prior_pics_flag, ps_bitstrm, 1);
    53      }
    54      UEV_PARSE("pic_parameter_set_id", pps_id, ps_bitstrm);
    55      if(pps_id < 0 || pps_id > MAX_PPS_CNT - 2)
    56      {
    57          return IHEVCD_INVALID_PARAMETER;
    58      }
    59
    60      /* Get the current PPS structure */
    61      ps_pps = ps_codec->s_parse.ps_pps_base + pps_id;
    62      if(0 == ps_pps->i1_pps_valid)
    63      {
    64          pps_t *ps_pps_ref = ps_codec->ps_pps_base;
    65          while(0 == ps_pps_ref->i1_pps_valid)
    66          {
    67              ps_pps_ref++;
    68              if((ps_pps_ref - ps_codec->ps_pps_base >= MAX_PPS_CNT - 1))
    69                  return IHEVCD_INVALID_HEADER;
    70          }
    71
    72          ihevcd_copy_pps(ps_codec, pps_id, ps_pps_ref->i1_pps_id);
    73      }
    74
    75      /* Get SPS id for the current PPS */
    76      sps_id = ps_pps->i1_sps_id;
    77
    78      /* Get the current SPS structure */
    79      ps_sps = ps_codec->s_parse.ps_sps_base + sps_id;
    80
    81      /* When the current slice is the first in a pic,
    82       *  check whether the previous frame is complete
    83       *  If the previous frame is incomplete -
    84       *  treat the remaining CTBs as skip */
    85      if((0 != ps_codec->u4_pic_cnt || ps_codec->i4_pic_present) &&
    86                      first_slice_in_pic_flag)
    87      {
    88          if(ps_codec->i4_pic_present)
    89          {
    90              slice_header_t *ps_slice_hdr_next;
    91              ps_codec->i4_slice_error = 1;
    92              ps_codec->s_parse.i4_cur_slice_idx--;
    93              if(ps_codec->s_parse.i4_cur_slice_idx < 0)
    94                  ps_codec->s_parse.i4_cur_slice_idx = 0;
    95
    96              ps_slice_hdr_next = ps_codec->s_parse.ps_slice_hdr_base + ((ps_codec->s_parse.i4_cur_slice_idx + 1) & (MAX_SLICE_HDR_CNT - 1));
    97              ps_slice_hdr_next->i2_ctb_x = 0;
    98              ps_slice_hdr_next->i2_ctb_y = ps_codec->s_parse.ps_sps->i2_pic_ht_in_ctb;
    99              return ret;
   100          }
   101          else
   102          {
   103              ps_codec->i4_slice_error = 0;
   104          }
   105      }
   106
   107      if(first_slice_in_pic_flag)
   108      {
   109          ps_codec->s_parse.i4_cur_slice_idx = 0;
   110      }
   111      else
   112      {
   113          /* If the current slice is not the first slice in the pic,
   114           * but the first one to be parsed, set the current slice indx to 1
   115           * Treat the first slice to be missing and copy the current slice header
   116           * to the first one */
   117          if(0 == ps_codec->i4_pic_present)
   118              ps_codec->s_parse.i4_cur_slice_idx = 1;
   119      }
   120
   121      ps_slice_hdr = ps_codec->s_parse.ps_slice_hdr_base + (ps_codec->s_parse.i4_cur_slice_idx & (MAX_SLICE_HDR_CNT - 1));
   122
   123
   124      if((ps_pps->i1_dependent_slice_enabled_flag) &&
   125         (!first_slice_in_pic_flag))
   126      {
   127          BITS_PARSE("dependent_slice_flag", value, ps_bitstrm, 1);
   128
   129          /* If dependendent slice, copy slice header from previous slice */
   130          if(value && (ps_codec->s_parse.i4_cur_slice_idx > 0))
   131          {
   132              ihevcd_copy_slice_hdr(ps_codec,
   133                                    (ps_codec->s_parse.i4_cur_slice_idx & (MAX_SLICE_HDR_CNT - 1)),
   134                                    ((ps_codec->s_parse.i4_cur_slice_idx - 1) & (MAX_SLICE_HDR_CNT - 1)));
   135          }
   136          ps_slice_hdr->i1_dependent_slice_flag = value;
   137      }
   138      else
   139      {
   140          ps_slice_hdr->i1_dependent_slice_flag = 0;
   141      }
   142      ps_slice_hdr->i1_nal_unit_type = i1_nal_unit_type;
   143      ps_slice_hdr->i1_pps_id = pps_id;
   144      ps_slice_hdr->i1_first_slice_in_pic_flag = first_slice_in_pic_flag;
   145
   146      ps_slice_hdr->i1_no_output_of_prior_pics_flag = 1;
   147      if((NAL_BLA_W_LP <= i1_nal_unit_type) &&
   148                      (NAL_RSV_RAP_VCL23          >= i1_nal_unit_type))
   149      {
   150          ps_slice_hdr->i1_no_output_of_prior_pics_flag = no_output_of_prior_pics_flag;
   151      }
   152      ps_slice_hdr->i1_pps_id = pps_id;
   153
   154      if(!ps_slice_hdr->i1_first_slice_in_pic_flag)
   155      {
   156          WORD32 num_bits;
   157
   158          /* Use CLZ to compute Ceil( Log2( PicSizeInCtbsY ) ) */
   159          num_bits = 32 - CLZ(ps_sps->i4_pic_size_in_ctb - 1);
   160          BITS_PARSE("slice_address", value, ps_bitstrm, num_bits);
   161
   162          slice_address = value;
